CREATE TABLE IF NOT EXISTS `sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `startTime` INTEGER NOT NULL, `endTime` INTEGER NOT NULL, `peakRpm` REAL NOT NULL, `peakBoostPsi` REAL NOT NULL, `peakOilTempC` REAL NOT NULL, `peakCoolantTempC` REAL NOT NULL, `peakSpeedKph` REAL NOT NULL, `totalFrames` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `snapshots` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `rpm` REAL NOT NULL, `speedKph` REAL NOT NULL, `boostKpa` REAL NOT NULL, `oilTempC` REAL NOT NULL, `coolantTempC` REAL NOT NULL, `throttlePct` REAL NOT NULL, FOREIGN KEY(`sessionId`) REFERENCES `sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_snapshots_sessionId` ON `snapshots` (`sessionId`);
CREATE TABLE IF NOT EXISTS `drives` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `startTime` INTEGER NOT NULL, `endTime` INTEGER NOT NULL, `name` TEXT, `hasGps` INTEGER NOT NULL, `sessionId` INTEGER NOT NULL, `distanceKm` REAL NOT NULL, `avgSpeedKph` REAL NOT NULL, `maxSpeedKph` REAL NOT NULL, `peakRpm` INTEGER NOT NULL, `peakBoostPsi` REAL NOT NULL, `peakOilTempC` REAL NOT NULL, `peakCoolantTempC` REAL NOT NULL, `peakLateralG` REAL NOT NULL, `fuelUsedL` REAL NOT NULL, `startFuelPct` REAL NOT NULL, `totalFrames` INTEGER NOT NULL, `driveModeBreakdown` TEXT NOT NULL, `weatherSummary` TEXT, `startOilTempC` REAL NOT NULL, `endOilTempC` REAL NOT NULL, `startCoolantTempC` REAL NOT NULL, `endCoolantTempC` REAL NOT NULL, `tags` TEXT NOT NULL, `aggressionScore` INTEGER NOT NULL, `avgFuelL100km` REAL NOT NULL, `avgFuelMpg` REAL NOT NULL, `thermalPeaksJson` TEXT, `avgStftPct` REAL, `avgLtftPct` REAL, `trimSamples` INTEGER NOT NULL, `pullCount` INTEGER, `knockPullCount` INTEGER, `peakBoostSource` TEXT, `boostPolicy` TEXT);
CREATE TABLE IF NOT EXISTS `drive_points` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `driveId` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `lat` REAL NOT NULL, `lng` REAL NOT NULL, `speedKph` REAL NOT NULL, `rpm` INTEGER NOT NULL, `gear` TEXT NOT NULL, `boostPsi` REAL NOT NULL, `coolantTempC` REAL NOT NULL, `oilTempC` REAL NOT NULL, `ambientTempC` REAL NOT NULL, `rduTempC` REAL NOT NULL, `ptuTempC` REAL NOT NULL, `fuelLevelPct` REAL NOT NULL, `lateralG` REAL NOT NULL, `throttlePct` REAL NOT NULL, `driveMode` TEXT NOT NULL, `wheelSpeedFL` REAL NOT NULL, `wheelSpeedFR` REAL NOT NULL, `wheelSpeedRL` REAL NOT NULL, `wheelSpeedRR` REAL NOT NULL, `tirePressLF` REAL NOT NULL, `tirePressRF` REAL NOT NULL, `tirePressLR` REAL NOT NULL, `tirePressRR` REAL NOT NULL, `tireTempLF` REAL NOT NULL, `tireTempRF` REAL NOT NULL, `tireTempLR` REAL NOT NULL, `tireTempRR` REAL NOT NULL, `longitudinalG` REAL NOT NULL, `brakePressure` REAL NOT NULL, `steeringAngle` REAL NOT NULL, `tipActualKpa` REAL NOT NULL, `boostTargetKpa` REAL NOT NULL, `wgdcPct` REAL NOT NULL, `isRaceReady` INTEGER NOT NULL, `boostSource` TEXT, `baroKpa` REAL, FOREIGN KEY(`driveId`) REFERENCES `drives`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_drive_points_driveId` ON `drive_points` (`driveId`);
CREATE TABLE IF NOT EXISTS `dtc_scans` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `moduleCount` INTEGER NOT NULL, `totalCodes` INTEGER NOT NULL, `scanDurationMs` INTEGER NOT NULL, `moduleStatuses` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `dtc_codes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `scanId` INTEGER NOT NULL, `module` TEXT NOT NULL, `code` TEXT NOT NULL, `description` TEXT NOT NULL, `status` TEXT NOT NULL, `freezeFrameJson` TEXT, `failureType` INTEGER, FOREIGN KEY(`scanId`) REFERENCES `dtc_scans`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_dtc_codes_scanId` ON `dtc_codes` (`scanId`);
CREATE INDEX IF NOT EXISTS `index_dtc_codes_code` ON `dtc_codes` (`code`);
CREATE TABLE IF NOT EXISTS `lap_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `driveId` INTEGER NOT NULL, `startFinishLat` REAL NOT NULL, `startFinishLng` REAL NOT NULL, `startFinishBearing` REAL NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `laps` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` INTEGER NOT NULL, `lapNumber` INTEGER NOT NULL, `lapTimeMs` INTEGER NOT NULL, `peakRpm` INTEGER NOT NULL, `peakBoostPsi` REAL NOT NULL, `peakLateralG` REAL NOT NULL, `peakSpeedKph` REAL NOT NULL, FOREIGN KEY(`sessionId`) REFERENCES `lap_sessions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_laps_sessionId` ON `laps` (`sessionId`);
CREATE TABLE IF NOT EXISTS `perf_runs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `driveId` INTEGER, `timestamp` INTEGER NOT NULL, `zeroTo60Ms` INTEGER NOT NULL, `zeroTo100Ms` INTEGER, `peakRpm` REAL NOT NULL, `peakBoostPsi` REAL NOT NULL, `launchRpm` REAL NOT NULL, `densityAltFt` REAL, `ambientTempC` REAL NOT NULL);
CREATE TABLE IF NOT EXISTS `drive_bookmarks` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `driveId` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `lat` REAL NOT NULL, `lng` REAL NOT NULL, `label` TEXT NOT NULL, `speedKph` REAL NOT NULL, `rpm` INTEGER NOT NULL, `boostPsi` REAL NOT NULL, FOREIGN KEY(`driveId`) REFERENCES `drives`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_drive_bookmarks_driveId` ON `drive_bookmarks` (`driveId`);
CREATE TABLE IF NOT EXISTS `knock_events` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `driveId` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `krDeg` REAL NOT NULL, `rpm` INTEGER NOT NULL, `boostPsi` REAL NOT NULL, `iatC` REAL NOT NULL, `throttlePct` REAL NOT NULL, `gearEst` INTEGER NOT NULL, `lat` REAL, `lng` REAL, `cylinder` INTEGER NOT NULL, `boostSource` TEXT, FOREIGN KEY(`driveId`) REFERENCES `drives`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_knock_events_driveId` ON `knock_events` (`driveId`);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
